'use strict';

const fs = require('node:fs');
const path = require('node:path');

const TODOS_FILE_NAME = 'todos.json';

/** An error caused by bad input or bad data; its message is safe to show to the user. */
class TodoError extends Error {
  constructor(message, { usage } = {}) {
    super(message);
    this.name = 'TodoError';
    this.usage = usage;
  }
}

function isValidTodo(todo) {
  return (
    todo !== null &&
    typeof todo === 'object' &&
    Number.isSafeInteger(todo.id) &&
    todo.id > 0 &&
    typeof todo.text === 'string' &&
    typeof todo.completed === 'boolean'
  );
}

/** Reads todos from `file`. A missing or empty file is treated as an empty list. */
function loadTodos(file) {
  let raw;
  try {
    raw = fs.readFileSync(file, 'utf8');
  } catch (err) {
    if (err.code === 'ENOENT') return [];
    throw err;
  }
  if (raw.trim() === '') return [];

  const name = path.basename(file);
  let data;
  try {
    data = JSON.parse(raw);
  } catch {
    throw new TodoError(`${name} is not valid JSON; fix or remove it and try again`);
  }
  if (!Array.isArray(data)) {
    throw new TodoError(`${name} must contain a JSON array of todos`);
  }
  const badIndex = data.findIndex((todo) => !isValidTodo(todo));
  if (badIndex !== -1) {
    throw new TodoError(`${name} contains an invalid todo at index ${badIndex}`);
  }
  return data;
}

/** Writes todos to `file` atomically, so a failed write can't leave a truncated file. */
function saveTodos(file, todos) {
  const tmp = `${file}.${process.pid}.tmp`;
  try {
    fs.writeFileSync(tmp, `${JSON.stringify(todos, null, 2)}\n`);
    fs.renameSync(tmp, file);
  } catch (err) {
    fs.rmSync(tmp, { force: true });
    throw err;
  }
}

/** Parses a user-supplied id string, accepting only positive integers. */
function parseId(value) {
  const id = Number(value);
  if (typeof value !== 'string' || !/^\d+$/.test(value) || !Number.isSafeInteger(id) || id < 1) {
    throw new TodoError(`Invalid id "${value}": must be a positive integer`);
  }
  return id;
}

function maxId(todos) {
  return todos.reduce((max, todo) => Math.max(max, todo.id), 0);
}

function findTodo(todos, id) {
  const todo = todos.find((t) => t.id === id);
  if (!todo) throw new TodoError(`No todo with id ${id}`);
  return todo;
}

/** Appends a new todo to `todos` and returns it. */
function addTodo(todos, text, now = new Date()) {
  const trimmed = typeof text === 'string' ? text.trim() : '';
  if (trimmed === '') throw new TodoError('Todo text cannot be empty');

  const todo = {
    // The next id is one past the current maximum, so ids of remaining todos never collide.
    id: maxId(todos) + 1,
    text: trimmed,
    completed: false,
    createdAt: now.toISOString(),
  };
  todos.push(todo);
  return todo;
}

/** Marks the todo with `id` as done. Reports whether it was already done. */
function completeTodo(todos, id) {
  const todo = findTodo(todos, id);
  const alreadyCompleted = todo.completed;
  todo.completed = true;
  return { todo, alreadyCompleted };
}

/** Removes the todo with `id` from `todos` and returns it. */
function deleteTodo(todos, id) {
  const index = todos.findIndex((t) => t.id === id);
  if (index === -1) throw new TodoError(`No todo with id ${id}`);
  return todos.splice(index, 1)[0];
}

function formatList(todos) {
  if (todos.length === 0) return 'No todos yet. Add one with: node index.js add "<text>"';

  // Right-align ids so the status column lines up once ids reach two or more digits.
  const width = String(maxId(todos)).length;
  return todos
    .map((t) => `${String(t.id).padStart(width)}. [${t.completed ? 'x' : ' '}] ${t.text}`)
    .join('\n');
}

module.exports = {
  TODOS_FILE_NAME,
  TodoError,
  loadTodos,
  saveTodos,
  parseId,
  addTodo,
  completeTodo,
  deleteTodo,
  formatList,
};
# cli-todo-app

A small command-line todo list for Node.js (18+), with no dependencies.

## Usage

```sh
node index.js add "Buy groceries"   # Added todo #1: Buy groceries
node index.js list                  # 1. [ ] Buy groceries
node index.js complete 1            # Completed todo #1: Buy groceries
node index.js delete 1              # Deleted todo #1: Buy groceries
node index.js help
```

Todos are stored in `todos.json` in the current directory. Each todo looks like:

```json
{ "id": 1, "text": "Buy groceries", "completed": false, "createdAt": "2026-09-30T12:00:00.000Z" }
```

Notes:

- Quotes around the text are optional: `node index.js add Buy groceries` works too.
- A new todo's id is one more than the highest existing id. Deleting a todo doesn't renumber the others.
- Errors (missing arguments, invalid or unknown ids, unknown commands, a corrupt `todos.json`) go to stderr and exit with code 1. A failed command never changes `todos.json`.

## Tests

```sh
npm test
```

The tests use Node's built-in test runner. `test/todos.test.js` covers the library in `lib/todos.js`, and `test/cli.test.js` runs the real CLI in temporary directories.
'use strict';

// End-to-end tests: each test runs the real CLI as a child process in a fresh temp directory.

const { describe, it, beforeEach, afterEach } = require('node:test');
const assert = require('node:assert/strict');
const { spawnSync } = require('node:child_process');
const fs = require('node:fs');
const os = require('node:os');
const path = require('node:path');

const CLI = path.join(__dirname, '..', 'index.js');

let cwd;
let todosFile;

function todo(...args) {
  const result = spawnSync(process.execPath, [CLI, ...args], { cwd, encoding: 'utf8' });
  return { code: result.status, stdout: result.stdout, stderr: result.stderr };
}

function readTodos() {
  return JSON.parse(fs.readFileSync(todosFile, 'utf8'));
}

function writeTodos(todos) {
  fs.writeFileSync(todosFile, JSON.stringify(todos));
}

/** Asserts the command failed with an error mentioning `pattern` and left todos.json unchanged. */
function assertFailsWithoutChanges(args, pattern) {
  const before = fs.existsSync(todosFile) ? fs.readFileSync(todosFile, 'utf8') : null;
  const result = todo(...args);
  assert.equal(result.code, 1, `expected exit code 1, got ${result.code}`);
  assert.equal(result.stdout, '');
  assert.match(result.stderr, /^Error: /);
  assert.match(result.stderr, pattern);
  const after = fs.existsSync(todosFile) ? fs.readFileSync(todosFile, 'utf8') : null;
  assert.equal(after, before, 'todos.json should not change on error');
}

beforeEach(() => {
  cwd = fs.mkdtempSync(path.join(os.tmpdir(), 'todo-cli-'));
  todosFile = path.join(cwd, 'todos.json');
});

afterEach(() => {
  fs.rmSync(cwd, { recursive: true, force: true });
});

describe('add', () => {
  it('adds a todo and stores it in todos.json in the current directory', () => {
    const result = todo('add', 'Buy groceries');
    assert.equal(result.code, 0);
    assert.equal(result.stdout, 'Added todo #1: Buy groceries\n');
    assert.equal(result.stderr, '');

    const todos = readTodos();
    assert.equal(todos.length, 1);
    assert.deepEqual(Object.keys(todos[0]).sort(), ['completed', 'createdAt', 'id', 'text']);
    assert.equal(todos[0].id, 1);
    assert.equal(todos[0].text, 'Buy groceries');
    assert.equal(todos[0].completed, false);
    assert.equal(new Date(todos[0].createdAt).toISOString(), todos[0].createdAt);
  });

  it('keeps a separate todo list per working directory', () => {
    todo('add', 'first dir');
    const firstDir = cwd;
    cwd = fs.mkdtempSync(path.join(os.tmpdir(), 'todo-cli-'));
    try {
      assert.equal(todo('add', 'second dir').stdout, 'Added todo #1: second dir\n');
      assert.equal(todo('list').stdout, '1. [ ] second dir\n');
    } finally {
      fs.rmSync(cwd, { recursive: true, force: true });
      cwd = firstDir;
    }
    assert.equal(todo('list').stdout, '1. [ ] first dir\n');
  });

  it('auto-increments ids across invocations', () => {
    assert.equal(todo('add', 'one').stdout, 'Added todo #1: one\n');
    assert.equal(todo('add', 'two').stdout, 'Added todo #2: two\n');
    assert.equal(todo('add', 'three').stdout, 'Added todo #3: three\n');
    assert.deepEqual(readTodos().map((t) => t.id), [1, 2, 3]);
  });

  it('joins unquoted words into a single todo', () => {
    const result = todo('add', 'Buy', 'groceries', 'today');
    assert.equal(result.code, 0);
    assert.equal(readTodos()[0].text, 'Buy groceries today');
  });

  it('trims surrounding whitespace', () => {
    todo('add', '   Buy groceries   ');
    assert.equal(readTodos()[0].text, 'Buy groceries');
  });

  it('preserves quotes, unicode, and shell-special characters', () => {
    const text = `Call "Mom" & Dad's café — $5 🎉`;
    assert.equal(todo('add', text).code, 0);
    assert.equal(readTodos()[0].text, text);
    assert.equal(todo('list').stdout, `1. [ ] ${text}\n`);
  });

  it('treats flag-like text as todo text', () => {
    assert.equal(todo('add', '--help').code, 0);
    assert.equal(readTodos()[0].text, '--help');
  });

  it('fails with usage when text is missing, without creating todos.json', () => {
    assertFailsWithoutChanges(['add'], /Missing todo text[\s\S]*Usage: node index\.js add/);
    assert.ok(!fs.existsSync(todosFile));
  });

  it('fails for empty or whitespace-only text', () => {
    assertFailsWithoutChanges(['add', ''], /cannot be empty/);
    assertFailsWithoutChanges(['add', '   '], /cannot be empty/);
    todo('add', 'existing');
    assertFailsWithoutChanges(['add', '\t'], /cannot be empty/);
  });
});

describe('list', () => {
  it('shows a friendly message when there are no todos', () => {
    const result = todo('list');
    assert.equal(result.code, 0);
    assert.match(result.stdout, /No todos yet/);
    assert.equal(result.stderr, '');
  });

  it('does not create todos.json', () => {
    todo('list');
    assert.ok(!fs.existsSync(todosFile));
  });

  it('shows the empty message when todos.json is an empty array or empty file', () => {
    writeTodos([]);
    assert.match(todo('list').stdout, /No todos yet/);
    fs.writeFileSync(todosFile, '');
    assert.match(todo('list').stdout, /No todos yet/);
  });

  it('shows the empty message after every todo is deleted', () => {
    todo('add', 'a');
    todo('delete', '1');
    assert.match(todo('list').stdout, /No todos yet/);
  });

  it('shows id, status indicator, and text for every todo in order', () => {
    todo('add', 'Buy groceries');
    todo('add', 'Walk the dog');
    todo('add', 'Write report');
    todo('complete', '2');

    const result = todo('list');
    assert.equal(result.code, 0);
    assert.equal(
      result.stdout,
      '1. [ ] Buy groceries\n2. [x] Walk the dog\n3. [ ] Write report\n',
    );
  });

  it('aligns the status column once ids reach two digits', () => {
    for (let i = 1; i <= 10; i++) todo('add', `task ${i}`);
    const lines = todo('list').stdout.trimEnd().split('\n');
    assert.equal(lines.length, 10);
    assert.equal(lines[0], ' 1. [ ] task 1');
    assert.equal(lines[9], '10. [ ] task 10');
  });

  it('ignores extra arguments', () => {
    todo('add', 'a');
    assert.equal(todo('list', 'extra').stdout, '1. [ ] a\n');
  });
});

describe('complete', () => {
  beforeEach(() => {
    todo('add', 'Buy groceries');
    todo('add', 'Walk the dog');
  });

  it('marks a todo as done and leaves others pending', () => {
    const result = todo('complete', '1');
    assert.equal(result.code, 0);
    assert.equal(result.stdout, 'Completed todo #1: Buy groceries\n');
    assert.deepEqual(readTodos().map((t) => t.completed), [true, false]);
  });

  it('preserves the other fields of the completed todo', () => {
    const before = readTodos()[0];
    todo('complete', '1');
    assert.deepEqual(readTodos()[0], { ...before, completed: true });
  });

  it('succeeds with a notice when the todo is already done', () => {
    todo('complete', '1');
    const before = fs.readFileSync(todosFile, 'utf8');
    const result = todo('complete', '1');
    assert.equal(result.code, 0);
    assert.match(result.stdout, /already completed/);
    assert.equal(fs.readFileSync(todosFile, 'utf8'), before);
  });

  it('fails with usage when the id is missing', () => {
    assertFailsWithoutChanges(['complete'], /Missing todo id[\s\S]*Usage: node index\.js complete <id>/);
  });

  for (const id of ['abc', '0', '-1', '1.5', '1e1', '']) {
    it(`fails for invalid id ${JSON.stringify(id)}`, () => {
      assertFailsWithoutChanges(['complete', id], /Invalid id/);
    });
  }

  it('fails for an id that does not exist', () => {
    assertFailsWithoutChanges(['complete', '99'], /No todo with id 99/);
  });

  it('fails for a previously deleted id', () => {
    todo('delete', '1');
    assertFailsWithoutChanges(['complete', '1'], /No todo with id 1/);
  });

  it('fails when given more than one id', () => {
    assertFailsWithoutChanges(['complete', '1', '2'], /Expected one todo id/);
  });

  it('fails when there are no todos at all', () => {
    fs.rmSync(todosFile);
    assertFailsWithoutChanges(['complete', '1'], /No todo with id 1/);
    assert.ok(!fs.existsSync(todosFile));
  });
});

describe('delete', () => {
  beforeEach(() => {
    todo('add', 'one');
    todo('add', 'two');
    todo('add', 'three');
  });

  it('removes the todo and keeps the others with their original ids', () => {
    const result = todo('delete', '2');
    assert.equal(result.code, 0);
    assert.equal(result.stdout, 'Deleted todo #2: two\n');
    assert.deepEqual(readTodos().map((t) => [t.id, t.text]), [[1, 'one'], [3, 'three']]);
