'use strict';

const fs = require('node:fs');
const path = require('node:path');

const TODOS_FILE_NAME = 'todos.json';

/** An error caused by bad input or bad data; its message is safe to show to the user. */
class TodoError extends Error {
  constructor(message, { usage } = {}) {
    super(message);
    this.name = 'TodoError';
    this.usage = usage;
  }
}

function isValidTodo(todo) {
  return (
    todo !== null &&
    typeof todo === 'object' &&
    Number.isSafeInteger(todo.id) &&
    todo.id > 0 &&
    typeof todo.text === 'string' &&
    typeof todo.completed === 'boolean'
  );
}

/** Reads todos from `file`. A missing or empty file is treated as an empty list. */
function loadTodos(file) {
  let raw;
  try {
    raw = fs.readFileSync(file, 'utf8');
  } catch (err) {
    if (err.code === 'ENOENT') return [];
    throw err;
  }
  if (raw.trim() === '') return [];

  const name = path.basename(file);
  let data;
  try {
    data = JSON.parse(raw);
  } catch {
    throw new TodoError(`${name} is not valid JSON; fix or remove it and try again`);
  }
  if (!Array.isArray(data)) {
    throw new TodoError(`${name} must contain a JSON array of todos`);
  }
  const badIndex = data.findIndex((todo) => !isValidTodo(todo));
  if (badIndex !== -1) {
    throw new TodoError(`${name} contains an invalid todo at index ${badIndex}`);
  }
  return data;
}

/** Writes todos to `file` atomically, so a failed write can't leave a truncated file. */
function saveTodos(file, todos) {
  const tmp = `${file}.${process.pid}.tmp`;
  try {
    fs.writeFileSync(tmp, `${JSON.stringify(todos, null, 2)}\n`);
    fs.renameSync(tmp, file);
  } catch (err) {
    fs.rmSync(tmp, { force: true });
    throw err;
  }
}

/** Parses a user-supplied id string, accepting only positive integers. */
function parseId(value) {
  const id = Number(value);
  if (typeof value !== 'string' || !/^\d+$/.test(value) || !Number.isSafeInteger(id) || id < 1) {
    throw new TodoError(`Invalid id "${value}": must be a positive integer`);
  }
  return id;
}

function maxId(todos) {
  return todos.reduce((max, todo) => Math.max(max, todo.id), 0);
}

function findTodo(todos, id) {
  const todo = todos.find((t) => t.id === id);
  if (!todo) throw new TodoError(`No todo with id ${id}`);
  return todo;
}

/** Appends a new todo to `todos` and returns it. */
function addTodo(todos, text, now = new Date()) {
  const trimmed = typeof text === 'string' ? text.trim() : '';
  if (trimmed === '') throw new TodoError('Todo text cannot be empty');

  const todo = {
    // The next id is one past the current maximum, so ids of remaining todos never collide.
    id: maxId(todos) + 1,
    text: trimmed,
    completed: false,
    createdAt: now.toISOString(),
  };
  todos.push(todo);
  return todo;
}

/** Marks the todo with `id` as done. Reports whether it was already done. */
function completeTodo(todos, id) {
  const todo = findTodo(todos, id);
  const alreadyCompleted = todo.completed;
  todo.completed = true;
  return { todo, alreadyCompleted };
}

/** Removes the todo with `id` from `todos` and returns it. */
function deleteTodo(todos, id) {
  const index = todos.findIndex((t) => t.id === id);
  if (index === -1) throw new TodoError(`No todo with id ${id}`);
  return todos.splice(index, 1)[0];
}

function formatList(todos) {
  if (todos.length === 0) return 'No todos yet. Add one with: node index.js add "<text>"';

  // Right-align ids so the status column lines up once ids reach two or more digits.
  const width = String(maxId(todos)).length;
  return todos
    .map((t) => `${String(t.id).padStart(width)}. [${t.completed ? 'x' : ' '}] ${t.text}`)
    .join('\n');
}

module.exports = {
  TODOS_FILE_NAME,
  TodoError,
  loadTodos,
  saveTodos,
  parseId,
  addTodo,
  completeTodo,
  deleteTodo,
  formatList,
};
# cli-todo-app

A small command-line todo list for Node.js (18+), with no dependencies.

## Usage

```sh
node index.js add "Buy groceries"   # Added todo #1: Buy groceries
node index.js list                  # 1. [ ] Buy groceries
node index.js complete 1            # Completed todo #1: Buy groceries
node index.js delete 1              # Deleted todo #1: Buy groceries
node index.js help
```

Todos are stored in `todos.json` in the current directory. Each todo looks like:

```json
{ "id": 1, "text": "Buy groceries", "completed": false, "createdAt": "2026-09-30T12:00:00.000Z" }
```

Notes:

- Quotes around the text are optional: `node index.js add Buy groceries` works too.
- A new todo's id is one more than the highest existing id. Deleting a todo doesn't renumber the others.
- Errors (missing arguments, invalid or unknown ids, unknown commands, a corrupt `todos.json`) go to stderr and exit with code 1. A failed command never changes `todos.json`.

## Tests

```sh
npm test
```

The tests use Node's built-in test runner. `test/todos.test.js` covers the library in `lib/todos.js`, and `test/cli.test.js` runs the real CLI in temporary directories.
